Write-EmbeddedFile -RelativePath "workspace\knowledge-graph\indexes\graph-index.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\knowledge-graph-entity-template.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\knowledge-graph-relationship-template.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\knowledge-graph\AIOfficeKnowledgeGraph.Common.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\knowledge-graph\New-AIOfficeKnowledgeGraphEntity.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\knowledge-graph\New-AIOfficeKnowledgeGraphRelationship.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\knowledge-graph\Update-AIOfficeKnowledgeGraphIndex.ps1" -Base64Content ""
