Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.5-Part-A-Knowledge-Graph-Architecture.md" -Base64Content ""
$Scripts = Get-ChildItem -LiteralPath "E:\AI\AI-Office\scripts\knowledge-graph" -Filter "*.ps1" -File
foreach ($Script in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors | ForEach-Object {$_.Message}) -join "; ")) }
}
$VersionPath = "E:\AI\AI-Office\config\identity\version.json"
if (Test-Path -LiteralPath $VersionPath -PathType Leaf) {
 $Version = Get-Content -LiteralPath $VersionPath -Raw | ConvertFrom-Json
 $Version.version = "1.5.0"
 $Version.release_name = "Knowledge Graph and Reasoning"
 $Version.status = "part_a_installed"
 $Version.installed_at = (Get-Date).ToString("o")
 $Version.next_planned_milestone = "1.5 Part B Extraction and Reasoning"
 $Version | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $VersionPath -Encoding UTF8
}
Write-Host ""
Write-Host "AI Office v1.5 Part A Knowledge Graph Architecture installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan